import"./chunk-ZW5NV4UO.js";var s={en:{title:"",description:"",eyebrow:"Communities",openApp:"Open Mawkingbird",heading:"Mastodon communities by interest",intro:["A new Mastodon account starts with an empty timeline. Each page gathers one interest: the hashtags people actually use, the people worth following, and the servers where the community meets. You can read all of it before you make an account.","Every page is written for its readers' language, and offers new local hashtags beside the busy English ones, so smaller language communities can grow their own."],moreHeading:"Just want people to follow?",allLanguages:"",tools:"Free tools for Mastodon and Bluesky",follow:"Who to follow on Mastodon",help:"Help",features:"Discover all Mawkingbird features"},de:{title:"Mastodon-Communities nach Interessen: Hashtags, Leute und Server",description:"Finde Mastodon-Communities nach Interessen: die Hashtags und Leute, denen es sich zu folgen lohnt, und die Server, auf denen sich jede Community trifft.",eyebrow:"Communities",openApp:"Mawkingbird \xF6ffnen",heading:"Mastodon-Communities nach Interessen",intro:["Ein neues Mastodon-Konto beginnt mit einer leeren Zeitleiste. Jede Seite hier sammelt ein Interesse: die Hashtags, die Leute wirklich verwenden, die Leute, denen es sich zu folgen lohnt, und die Server, auf denen sich die Community trifft. Du kannst alles lesen, bevor du ein Konto anlegst.","Jede Seite ist f\xFCr deutschsprachige Leserinnen und Leser geschrieben und schl\xE4gt neben den gro\xDFen englischen Hashtags auch deutsche vor, damit kleinere Sprachgemeinschaften wachsen k\xF6nnen."],moreHeading:"Mehr",allLanguages:"Alle Themen in allen Sprachen (auf Englisch)",tools:"Kostenlose Werkzeuge f\xFCr Mastodon und Bluesky",help:"Hilfe (auf Englisch)",features:"Alles, was Mawkingbird kann (auf Englisch)"},fr:{title:"Communaut\xE9s Mastodon par centre d\u2019int\xE9r\xEAt : hashtags, comptes et serveurs",description:"Trouve les communaut\xE9s Mastodon par centre d\u2019int\xE9r\xEAt : les hashtags et les comptes \xE0 suivre, et les serveurs o\xF9 chaque communaut\xE9 se retrouve.",eyebrow:"Communaut\xE9s",openApp:"Ouvrir Mawkingbird",heading:"Communaut\xE9s Mastodon par centre d\u2019int\xE9r\xEAt",intro:["Un nouveau compte Mastodon commence avec un fil vide. Chaque page rassemble un centre d\u2019int\xE9r\xEAt : les hashtags vraiment utilis\xE9s, les comptes \xE0 suivre et les serveurs o\xF9 la communaut\xE9 se retrouve. Tu peux tout lire avant de cr\xE9er un compte.","Chaque page est \xE9crite pour les lecteurs francophones et propose des hashtags en fran\xE7ais \xE0 c\xF4t\xE9 des grands hashtags anglais, pour que les communaut\xE9s francophones grandissent aussi."],moreHeading:"Et aussi",allLanguages:"Tous les sujets, dans toutes les langues (en anglais)",tools:"Outils gratuits pour Mastodon et Bluesky",help:"Aide (en anglais)",features:"Tout ce que fait Mawkingbird (en anglais)"},es:{title:"Comunidades de Mastodon por intereses: hashtags, personas y servidores",description:"Encuentra comunidades de Mastodon por intereses: los hashtags y las personas que vale la pena seguir, y los servidores donde se re\xFAne cada comunidad.",eyebrow:"Comunidades",openApp:"Abrir Mawkingbird",heading:"Comunidades de Mastodon por intereses",intro:["Una cuenta nueva de Mastodon empieza con una cronolog\xEDa vac\xEDa. Cada p\xE1gina re\xFAne un inter\xE9s: los hashtags que la gente usa de verdad, las personas que vale la pena seguir y los servidores donde se re\xFAne la comunidad. Puedes leerlo todo antes de crear una cuenta.","Cada p\xE1gina est\xE1 escrita para lectores en espa\xF1ol y propone hashtags en espa\xF1ol junto a los grandes hashtags en ingl\xE9s, para que las comunidades hispanohablantes tambi\xE9n crezcan."],moreHeading:"M\xE1s",allLanguages:"Todos los temas, en todos los idiomas (en ingl\xE9s)",tools:"Herramientas gratuitas para Mastodon y Bluesky",help:"Ayuda (en ingl\xE9s)",features:"Todo lo que hace Mawkingbird (en ingl\xE9s)"},it:{title:"Comunit\xE0 Mastodon per interesse: hashtag, persone e server",description:"Trova le comunit\xE0 Mastodon per interesse: gli hashtag e le persone da seguire, e i server dove si ritrova ogni comunit\xE0.",eyebrow:"Comunit\xE0",openApp:"Apri Mawkingbird",heading:"Comunit\xE0 Mastodon per interesse",intro:["Un nuovo account Mastodon parte con una timeline vuota. Ogni pagina raccoglie un interesse: gli hashtag che le persone usano davvero, le persone da seguire e i server dove si ritrova la comunit\xE0. Puoi leggere tutto prima di creare un account.","Ogni pagina \xE8 scritta per chi legge in italiano e propone hashtag in italiano accanto ai grandi hashtag in inglese, cos\xEC anche le comunit\xE0 italiane possono crescere."],moreHeading:"Altro",allLanguages:"Tutti gli argomenti, in tutte le lingue (in inglese)",tools:"Strumenti gratuiti per Mastodon e Bluesky",help:"Aiuto (in inglese)",features:"Tutto quello che fa Mawkingbird (in inglese)"},ja:{title:"\u8208\u5473\u5225\u306EMastodon\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3\uFF1A\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3001\u4EBA\u3001\u30B5\u30FC\u30D0\u30FC",description:"\u8208\u5473\u304B\u3089Mastodon\u306E\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3\u3092\u898B\u3064\u3051\u307E\u3057\u3087\u3046\u3002\u30D5\u30A9\u30ED\u30FC\u3059\u308B\u4FA1\u5024\u306E\u3042\u308B\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3068\u4EBA\u3001\u305D\u3057\u3066\u5404\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3\u304C\u96C6\u307E\u308B\u30B5\u30FC\u30D0\u30FC\u3092\u7D39\u4ECB\u3057\u307E\u3059\u3002",eyebrow:"\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3",openApp:"Mawkingbird \u3092\u958B\u304F",heading:"\u8208\u5473\u5225\u306EMastodon\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3",intro:["\u65B0\u3057\u3044Mastodon\u30A2\u30AB\u30A6\u30F3\u30C8\u306E\u30BF\u30A4\u30E0\u30E9\u30A4\u30F3\u306F\u7A7A\u3063\u307D\u304B\u3089\u59CB\u307E\u308A\u307E\u3059\u3002\u5404\u30DA\u30FC\u30B8\u306F\u3072\u3068\u3064\u306E\u8208\u5473\u306B\u3064\u3044\u3066\u3001\u5B9F\u969B\u306B\u4F7F\u308F\u308C\u3066\u3044\u308B\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3001\u30D5\u30A9\u30ED\u30FC\u3059\u308B\u4FA1\u5024\u306E\u3042\u308B\u4EBA\u3001\u30B3\u30DF\u30E5\u30CB\u30C6\u30A3\u304C\u96C6\u307E\u308B\u30B5\u30FC\u30D0\u30FC\u3092\u307E\u3068\u3081\u3066\u3044\u307E\u3059\u3002\u30A2\u30AB\u30A6\u30F3\u30C8\u3092\u4F5C\u308B\u524D\u306B\u3059\u3079\u3066\u8AAD\u3081\u307E\u3059\u3002","\u5404\u30DA\u30FC\u30B8\u306F\u65E5\u672C\u8A9E\u306E\u8AAD\u8005\u5411\u3051\u306B\u66F8\u304B\u308C\u3066\u304A\u308A\u3001\u82F1\u8A9E\u306E\u5927\u304D\u306A\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u306B\u52A0\u3048\u3066\u65E5\u672C\u8A9E\u306E\u30CF\u30C3\u30B7\u30E5\u30BF\u30B0\u3082\u63D0\u6848\u3057\u307E\u3059\u3002"],moreHeading:"\u307B\u304B\u306B\u3082",allLanguages:"\u3059\u3079\u3066\u306E\u30C6\u30FC\u30DE\u3068\u3059\u3079\u3066\u306E\u8A00\u8A9E\uFF08\u82F1\u8A9E\uFF09",tools:"Mastodon\u3068Bluesky\u306E\u7121\u6599\u30C4\u30FC\u30EB",help:"\u30D8\u30EB\u30D7\uFF08\u82F1\u8A9E\uFF09",features:"Mawkingbird\u3067\u3067\u304D\u308B\u3053\u3068\uFF08\u82F1\u8A9E\uFF09"}};function a(e){let n=s[e];if(!n)throw new Error(`No communities hub copy for ${e}`);return n}export{s as HUB_COPY,a as hubCopyFor};
